def main(argv=None):
    args = parse_args(argv)
    sql_text = args.sql
    if sql_text is None:
        # 先读查询文件：文件类失败时不接触源库与输出目标
        try:
            sql_text = read_sql_file(args.sql_file)
        except ValueError as exc:
            die(str(exc))
    try:
        if args.preview is not None:
            # 预览：标准输出只写 CSV 本身，成功时不追加任何提示
            preview_csv(
                args.db,
                sql_text,
                args.preview,
                params=args.params,
                null_text=args.null_text,
            )
            return 0
        if args.format == "csv":
            row_count = export_csv(
                args.db,
                sql_text,
                args.output,
                params=args.params,
                null_text=args.null_text,
            )
        else:
            row_count = export_html(
                args.db,
                sql_text,
                args.output,
                params=args.params,
                null_text=args.null_text,
                # 未提供 --description 时为 None，与空字符串同样不输出说明区域
                description=args.description or "",
                # 未提供 --title 时为 None，由 export_html 使用默认“查询报告”
                title=args.title if args.title is not None else "查询报告",
            )
    except ValueError as exc:
        die(str(exc))
    except sqlite3.Error as exc:
        die("数据库错误：%s" % exc)
    except OSError as exc:
        die("文件错误：%s" % exc)
    print("已导出 %d 行数据：%s" % (row_count, args.output))
    return 0


if __name__ == "__main__":
    sys.exit(main())

